import{_ as c,o as e,c as s}from"./chunks/framework.D4oetGi0.js";const r=JSON.parse('{"title":"Kubernetes 常用运维命令","titleTemplate":":title · 知行笔记","description":"使用 kubectl 检查集群和应用状态、查看日志、发布与回滚服务，以及排查配置、存储、网络和节点问题。 操作前确认集群和命名空间，将示例中的 demo 、 demo-api 、Pod、节点名、镜像及地址替换为实际值。读取 Secret、进","frontmatter":{"title":"Kubernetes 常用运维命令","titleTemplate":":title · 知行笔记","description":"使用 kubectl 检查集群和应用状态、查看日志、发布与回滚服务，以及排查配置、存储、网络和节点问题。 操作前确认集群和命名空间，将示例中的 demo 、 demo-api 、Pod、节点名、镜像及地址替换为实际值。读取 Secret、进","kb":"{\\"site\\":{\\"title\\":\\"知行笔记\\",\\"description\\":\\"把实践整理成知识，让经验随时可查。\\",\\"publicRepository\\":\\"alcq77/alcq77.github.io\\",\\"localOnly\\":false,\\"support\\":{\\"wechat\\":\\"assets/support/wechat.jpg\\",\\"alipay\\":\\"assets/support/alipay.jpg\\"}},\\"docs\\":[{\\"id\\":\\"docker-compose-operations-commands\\",\\"title\\":\\"Docker 与 Docker Compose 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kafka-operations\\",\\"title\\":\\"Kafka 部署、运维与故障排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-internals\\",\\"title\\":\\"Kafka 核心机制与源码排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-reliability\\",\\"title\\":\\"Kafka 消息生产、消费与可靠性实践\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kubernetes-operations-commands\\",\\"title\\":\\"Kubernetes 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-cluster-troubleshooting\\",\\"title\\":\\"Kubernetes 集群搭建、维护与故障排查\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-application-practice\\",\\"title\\":\\"Kubernetes 应用部署与配置实践\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"linux-system-status-commands\\",\\"title\\":\\"Linux 常用系统状态查看命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-service-check-start-troubleshooting\\",\\"title\\":\\"Linux 服务检查、启动与排障\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-systemd-autostart\\",\\"title\\":\\"Linux 服务开机自启与 systemd 管理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-server-operations-commands\\",\\"title\\":\\"Linux 服务器常用运维命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-kernel-troubleshooting\\",\\"title\\":\\"Linux 内核问题排查与处理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-performance-troubleshooting\\",\\"title\\":\\"Linux 性能瓶颈排查与优化\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"nginx-operations\\",\\"title\\":\\"Nginx 配置、部署与日常运维\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"}],\\"doc\\":{\\"id\\":\\"kubernetes-operations-commands\\",\\"title\\":\\"Kubernetes 常用运维命令\\",\\"category\\":\\"容器运维\\"},\\"content\\":\\"\\\\u003cdiv class=\\\\\\"article-head\\\\\\">\\\\u003cdiv class=\\\\\\"eyebrow\\\\\\">容器运维\\\\u003c/div>\\\\u003ch1>Kubernetes 常用运维命令\\\\u003c/h1>\\\\u003cdiv class=\\\\\\"article-meta\\\\\\">\\\\u003cspan class=\\\\\\"author-avatar\\\\\\">知\\\\u003c/span>\\\\u003cspan>知行笔记\\\\u003c/span>\\\\u003cspan class=\\\\\\"meta-dot\\\\\\">·\\\\u003c/span>\\\\u003cspan>约 26 分钟阅读\\\\u003c/span>\\\\u003c/div>\\\\u003cdiv class=\\\\\\"tag-row\\\\\\">\\\\u003cspan class=\\\\\\"tag\\\\\\">kubernetes\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">kubectl\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">k8s\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">operations\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">troubleshooting\\\\u003c/span>\\\\u003c/div>\\\\u003c/div>\\\\u003carticle class=\\\\\\"markdown-body\\\\\\">\\\\u003cp>使用 kubectl 检查集群和应用状态、查看日志、发布与回滚服务，以及排查配置、存储、网络和节点问题。\\\\u003c/p>\\\\n\\\\u003cp>操作前确认集群和命名空间，将示例中的 \\\\u003ccode>demo\\\\u003c/code>、\\\\u003ccode>demo-api\\\\u003c/code>、Pod、节点名、镜像及地址替换为实际值。读取 Secret、进入容器、修改配置、重启和删除资源需要对应 RBAC 权限。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"1-集群上下文和命名空间\\\\\\">1. 集群、上下文和命名空间\\\\u003c/h2>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>安装 kubectl：选择版本、下载、校验及普通用户安装\\\\u003c/summary>\\\\n\\\\u003cp>kubectl只是客户端，不会创建Kubernetes集群。先向管理员确认API Server版本，客户端版本一般应在服务端前后一个小版本内；不要在不知集群版本时直接下载最新版。\\\\u003c/p>\\\\n\\\\u003cp>CentOS 7可以在已有兼容客户端上维护集群，但客户端可执行不代表这台机器适合安装新版Kubernetes节点。旧客户端、内核和运行时分别核对；本机工具不兼容时在受维护的管理机上使用匹配集群版本的kubectl，不临时替换生产节点组件。详见\\\\u003ca href=\\\\\\"https://kubernetes.io/releases/version-skew-policy/\\\\\\">版本偏差规则\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003cp>下面演示Linux amd64下载流程，\\\\u003ccode>v1.35.0\\\\u003c/code>仅为固定版本示例，应改为与集群匹配、经批准的补丁版本；\\\\u003ccode>uname -m\\\\u003c/code>若为aarch64，下载架构改为arm64。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uname\\\\u003c/span> -m\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">mkdir\\\\u003c/span> -p \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/downloads/kubectl&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cd\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/downloads/kubectl&quot;\\\\u003c/span>\\\\nkubectl_version=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;v1.35.0&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 按集群版本调整\\\\u003c/span>\\\\nkubectl_arch=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;amd64&#x27;\\\\u003c/span>     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 按实际架构调整\\\\u003c/span>\\\\ncurl -fLO \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;https://dl.k8s.io/release/\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$kubectl_version\\\\u003c/span>/bin/linux/\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$kubectl_arch\\\\u003c/span>/kubectl&quot;\\\\u003c/span>\\\\ncurl -fLO \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;https://dl.k8s.io/release/\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$kubectl_version\\\\u003c/span>/bin/linux/\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$kubectl_arch\\\\u003c/span>/kubectl.sha256&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">printf\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;%s  kubectl\\\\\\\\n&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-subst\\\\\\">$(cat kubectl.sha256)\\\\u003c/span>&quot;\\\\u003c/span> | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sha256sum\\\\u003c/span> --check\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：最后应显示 \\\\u003ccode>kubectl: OK\\\\u003c/code>。任一步下载失败或校验不符就停止，不安装该文件。\\\\u003c/p>\\\\n\\\\u003cp>上面的 \\\\u003ccode>|\\\\u003c/code> 把 \\\\u003ccode>printf\\\\u003c/code> 生成的“校验值＋文件名”作为标准输入传给 \\\\u003ccode>sha256sum --check\\\\u003c/code>，不需要再创建一个校验清单文件。\\\\u003ccode>$(cat kubectl.sha256)\\\\u003c/code> 则是命令替换，先读取校验文件内容，再放到 \\\\u003ccode>printf\\\\u003c/code> 的参数中。\\\\u003c/p>\\\\n\\\\u003cp>校验成功后，有管理员授权可安装到系统路径：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> install -o root -g root -m 0755 kubectl /usr/local/bin/kubectl\\\\nkubectl version --client\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：没有sudo时可改为个人目录，不需要改变系统权限：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">mkdir\\\\u003c/span> -p \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/.local/bin&quot;\\\\u003c/span>\\\\ninstall -m 0755 kubectl \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/.local/bin/kubectl&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> PATH=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/.local/bin:\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$PATH\\\\u003c/span>&quot;\\\\u003c/span>\\\\nkubectl version --client\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>export\\\\u003c/code>仅对当前shell及后代生效；长期使用将同样PATH配置放进自己所用shell的配置文件，避免重复追加。集群访问还需要管理员发放的个人kubeconfig，不能复制他人的cluster-admin凭据。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">KUBECONFIG=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/.kube/demo-config&quot;\\\\u003c/span> kubectl config current-context\\\\nKUBECONFIG=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/.kube/demo-config&quot;\\\\u003c/span> kubectl -n demo auth can-i get pods\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：这里假设管理员提供的配置已安全放在该路径。能输出客户端版本不代表已有集群访问权；本机sudo也不能解决Kubernetes RBAC的Forbidden。步骤见 \\\\u003ca href=\\\\\\"https://kubernetes.io/docs/tasks/tools/install-kubectl-linux/\\\\\\">kubectl官方安装说明\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003c/details>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl version --client                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 本机客户端版本\\\\u003c/span>\\\\nkubectl version                          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 客户端与服务端版本\\\\u003c/span>\\\\nkubectl config get-contexts              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 上下文列表\\\\u003c/span>\\\\nkubectl config current-context           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前集群上下文\\\\u003c/span>\\\\nkubectl cluster-info                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 集群服务信息\\\\u003c/span>\\\\nkubectl get namespaces                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 命名空间\\\\u003c/span>\\\\nkubectl api-resources                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 实际可用资源类型\\\\u003c/span>\\\\nkubectl explain deployment.spec          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 资源字段说明\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>current-context\\\\u003c/code> 返回测试集群名后，才在该集群排查。API资源以集群实际提供的为准，不假设每个集群都安装了 Ingress Controller、metrics-server 或自定义资源。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl config use-context demo-cluster                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 切换默认上下文\\\\u003c/span>\\\\nkubectl config set-context --current --namespace=demo    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 更改当前上下文默认命名空间\\\\u003c/span>\\\\nkubectl --context demo-cluster -n demo get pods          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 单次显式指定目标\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：脚本或多集群运维优先显式使用 \\\\u003ccode>--context\\\\u003c/code> 与 \\\\u003ccode>-n\\\\u003c/code>，避免默认目标变化后误操作。kubeconfig 可能含凭证，不要直接公开或上传。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"2-全局巡检与资源列表\\\\\\">2. 全局巡检与资源列表\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl get nodes -o wide                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 节点、版本与地址\\\\u003c/span>\\\\nkubectl get pods -A -o wide                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 全集群 Pod\\\\u003c/span>\\\\nkubectl -n demo get deploy,sts,ds,job,cronjob \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 常见工作负载\\\\u003c/span>\\\\nkubectl -n demo get svc,ingress              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 服务和入口\\\\u003c/span>\\\\nkubectl -n demo get pvc                      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 存储申请\\\\u003c/span>\\\\nkubectl -n demo get events --sort-by=.metadata.creationTimestamp \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 最近事件顺序\\\\u003c/span>\\\\nkubectl -n demo get pods -w                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 持续观察变化\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>READY 1/2\\\\u003c/code> 表示两个容器中只有一个就绪；\\\\u003ccode>Running\\\\u003c/code> 不等于所有容器或业务都正常。\\\\u003ccode>get all\\\\u003c/code> 不包含全部资源，ConfigMap、Secret、PVC、Ingress 等需单独查询。\\\\u003ccode>-w\\\\u003c/code> 按 \\\\u003ccode>Ctrl+C\\\\u003c/code> 退出观察。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"3-定位应用与查看详情\\\\\\">3. 定位应用与查看详情\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo get pods -l app=demo-api -o wide \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 按实际标签定位\\\\u003c/span>\\\\nkubectl -n demo describe deployment demo-api   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 工作负载详情与事件\\\\u003c/span>\\\\nkubectl -n demo describe pod demo-api-abc-123   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 调度、镜像、探针、退出原因\\\\u003c/span>\\\\nkubectl -n demo get pod demo-api-abc-123 -o yaml \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Pod最终配置\\\\u003c/span>\\\\nkubectl -n demo get pod demo-api-abc-123 -o jsonpath=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;{.metadata.ownerReferences}&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 控制器归属\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>describe pod\\\\u003c/code> 底部 Events 中出现 \\\\u003ccode>FailedMount\\\\u003c/code>，先查卷和权限；出现 \\\\u003ccode>FailedScheduling\\\\u003c/code>，先查资源、污点、亲和性和PVC，而非直接删Pod。YAML可能含字面量环境变量等敏感配置，分享前脱敏。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"4-日志当前上次多个容器\\\\\\">4. 日志：当前、上次、多个容器\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo logs demo-api-abc-123 -c app --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span>=100 --timestamps \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 指定容器\\\\u003c/span>\\\\nkubectl -n demo logs demo-api-abc-123 -c app --since=30m             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 最近30分钟\\\\u003c/span>\\\\nkubectl -n demo logs demo-api-abc-123 -c app --previous             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 上次退出实例\\\\u003c/span>\\\\nkubectl -n demo logs -f demo-api-abc-123 -c app --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span>=100           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 实时追踪\\\\u003c/span>\\\\nkubectl -n demo logs -l app=demo-api --all-containers=\\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">true\\\\u003c/span> --prefix=\\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">true\\\\u003c/span> --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span>=100 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 标签聚合\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：Pod出现 \\\\u003ccode>CrashLoopBackOff\\\\u003c/code>，优先看 \\\\u003ccode>--previous\\\\u003c/code>，当前实例可能尚未打印完整错误。init容器日志也用其名字指定 \\\\u003ccode>-c\\\\u003c/code>。上次日志是否还在取决于容器与节点保留情况，不是永久历史；长期检索需要集中日志。\\\\u003c/p>\\\\n\\\\u003cp>日志跟踪按 \\\\u003ccode>Ctrl+C\\\\u003c/code> 只结束查看。\\\\u003ccode>logs\\\\u003c/code> 读取标准输出与错误，不主动读取应用在PVC中的日志文件。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"5-容器命令文件复制和临时调试\\\\\\">5. 容器命令、文件复制和临时调试\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">exec\\\\u003c/span> -it demo-api-abc-123 -c app -- sh \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 进入容器\\\\u003c/span>\\\\nkubectl -n demo \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">exec\\\\u003c/span> demo-api-abc-123 -c app -- \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /etc/resolv.conf \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># DNS配置\\\\u003c/span>\\\\nkubectl -n demo \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cp\\\\u003c/span> demo-api-abc-123:/tmp/report.txt ./report.txt -c app \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 拷出\\\\u003c/span>\\\\nkubectl -n demo \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cp\\\\u003c/span> ./config-test.yaml demo-api-abc-123:/tmp/config-test.yaml -c app \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 拷入临时位置\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>--\\\\u003c/code> 后面是容器内命令；镜像没有shell时 \\\\u003ccode>sh\\\\u003c/code> 也不能用。\\\\u003ccode>kubectl cp\\\\u003c/code> 通常要求容器内有 \\\\u003ccode>tar\\\\u003c/code>，不适合当作完整备份方案；容器文件修改可能随重建丢失。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo debug pod/demo-api-abc-123 -it \\\\\\\\\\\\n  --image=busybox:1.37 --target=app -- sh\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：给目标Pod添加临时调试容器，需要集群功能、运行时和权限支持；会修改Pod，可能被安全策略拒绝。使用受信任的调试镜像，结束shell不代表调试容器记录从Pod规格中消失。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"6-cpu内存限制与-oom\\\\\\">6. CPU、内存、限制与 OOM\\\\u003c/h2>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>kubectl top 报错：检查指标服务，不是再装一个top命令\\\\u003c/summary>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl get apiservice v1beta1.metrics.k8s.io\\\\nkubectl -n kube-system get deployment metrics-server\\\\nkubectl -n kube-system logs deployment/metrics-server --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span>=100\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：资源不存在或指标API不可用时，需要集群管理员检查或部署与集群兼容的 \\\\u003ca href=\\\\\\"https://github.com/kubernetes-sigs/metrics-server\\\\\\">metrics-server\\\\u003c/a>。部署名称/命名空间可能不同，按实际安装查找。不要直接把最新版清单套进旧集群，或为了绕过证书问题默认加跳过kubelet证书校验的参数。\\\\u003c/p>\\\\n\\\\u003c/details>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl top nodes                                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 节点资源\\\\u003c/span>\\\\nkubectl -n demo top pods --containers              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 容器资源\\\\u003c/span>\\\\nkubectl -n demo describe pod demo-api-abc-123       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># requests/limits、last state\\\\u003c/span>\\\\nkubectl describe node worker-1                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 可分配资源、已分配请求、压力\\\\u003c/span>\\\\nkubectl -n demo get resourcequota,limitrange        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 命名空间约束\\\\u003c/span>\\\\nkubectl -n demo get hpa                            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 自动扩缩容状态\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>top\\\\u003c/code> 需要资源指标API（通常由metrics-server提供），不是历史监控。\\\\u003ccode>OOMKilled\\\\u003c/code> 结合内存limit、节点压力和应用峰值判断；CPU限制可能导致节流，不一定表现为进程退出。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"7-清单校验比较与应用\\\\\\">7. 清单校验、比较与应用\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl apply --dry-run=client -f deployment.yaml -o yaml \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 客户端预览\\\\u003c/span>\\\\nkubectl apply --dry-run=server -f deployment.yaml         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 服务端校验，不落库\\\\u003c/span>\\\\nkubectl diff -f deployment.yaml                          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 对比现有配置\\\\u003c/span>\\\\nkubectl apply -f deployment.yaml                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 应用变更\\\\u003c/span>\\\\nkubectl -n demo rollout status deployment/demo-api --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span>=180s \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 等待滚动结果\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：清单中明确 \\\\u003ccode>metadata.namespace: demo\\\\u003c/code>，先校验和diff，再apply。\\\\u003ccode>diff\\\\u003c/code> 有差异时退出码为1，不必把它当成命令故障；输出可能含配置内容，分享前检查敏感值。dry-run不验证实际业务或外部数据库。\\\\u003c/p>\\\\n\\\\u003cp>如果资源由 Helm、Operator 或 GitOps 管理，应更新其源配置，临时 \\\\u003ccode>edit/apply\\\\u003c/code> 可能被控制器覆盖。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"8-更新重启回滚与扩缩容\\\\\\">8. 更新、重启、回滚与扩缩容\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">set\\\\u003c/span> image deployment/demo-api app=registry.example.com/team/demo-api:1.1.0 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 更新镜像\\\\u003c/span>\\\\nkubectl -n demo rollout status deployment/demo-api --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span>=180s \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看发布结果\\\\u003c/span>\\\\nkubectl -n demo rollout \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">history\\\\u003c/span> deployment/demo-api              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 修订历史\\\\u003c/span>\\\\nkubectl -n demo rollout \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">history\\\\u003c/span> deployment/demo-api --revision=2 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 指定修订\\\\u003c/span>\\\\nkubectl -n demo rollout undo deployment/demo-api --to-revision=2 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 回滚\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>app\\\\u003c/code> 是容器名，必须与清单一致；镜像地址为占位示例。回滚依赖保留的修订，只回滚Pod模板，不会恢复数据库、独立ConfigMap或PVC中的数据。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo rollout restart deployment/demo-api    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 触发滚动重建\\\\u003c/span>\\\\nkubectl -n demo rollout pause deployment/demo-api      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 暂停Deployment滚动\\\\u003c/span>\\\\nkubectl -n demo rollout resume deployment/demo-api     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 恢复\\\\u003c/span>\\\\nkubectl -n demo scale deployment/demo-api --replicas=3 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 改副本数\\\\u003c/span>\\\\nkubectl -n demo get hpa demo-api                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 核对HPA\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：这些操作可能影响流量与容量，按需单独执行。HPA可再次调整人工设置的副本数；暂停滚动不等于暂停现有业务。滚动可用性取决于副本、探针、更新策略和容量，不能默认零中断。\\\\u003c/p>\\\\n\\\\u003cp>删除受控制器管理的Pod通常会被重建，不是永久停服；缩容到0也要考虑HPA或其他控制器。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"9-configmapsecret-和配置生效\\\\\\">9. ConfigMap、Secret 和配置生效\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo get configmap                      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># ConfigMap列表\\\\u003c/span>\\\\nkubectl -n demo describe configmap demo-config     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 内容与键，分享前检查\\\\u003c/span>\\\\nkubectl -n demo get secret                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Secret名称与类型，不解码\\\\u003c/span>\\\\nkubectl -n demo get secret demo-secret -o jsonpath=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;{.type}&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 仅查询类型\\\\u003c/span>\\\\nkubectl -n demo create configmap demo-config --from-file=application.yaml --dry-run=client -o yaml\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：最后一条只生成清单，不创建资源；可通过项目审批流程应用。Secret的base64不是加密，不把解码结果、完整Secret YAML或带秘密的命令记录公开。\\\\u003c/p>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>配置注入方式\\\\u003c/th>\\\\n\\\\u003cth>更新后的常见行为\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>环境变量\\\\u003c/td>\\\\n\\\\u003ctd>已运行进程不会自动更新，需要重建Pod\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>普通投射卷\\\\u003c/td>\\\\n\\\\u003ctd>通常最终更新，有传播延迟；应用仍需重新读取\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>\\\\u003ccode>subPath\\\\u003c/code> 挂载\\\\u003c/td>\\\\n\\\\u003ctd>不会自动接收对应ConfigMap/Secret更新\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>immutable对象\\\\u003c/td>\\\\n\\\\u003ctd>不能直接修改内容，需要采用新对象等方式\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>示例：ConfigMap已更新而应用还是旧配置，先查注入方式及应用重载能力，再决定是否滚动重启，不直接假设更新失败。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"10-servicednsendpointslice-与-ingress\\\\\\">10. Service、DNS、EndpointSlice 与 Ingress\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo get svc demo-api -o wide          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Service类型与端口\\\\u003c/span>\\\\nkubectl -n demo describe svc demo-api            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># selector、端口、后端信息\\\\u003c/span>\\\\nkubectl -n demo get endpointslices -l kubernetes.io/service-name=demo-api -o wide\\\\nkubectl -n demo get pods --show-labels           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 核对 selector\\\\u003c/span>\\\\nkubectl -n demo get ingress                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 入口地址\\\\u003c/span>\\\\nkubectl -n demo describe ingress demo-web        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 规则、控制器事件\\\\u003c/span>\\\\nkubectl -n demo get networkpolicy               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 网络访问限制\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：Service没有可用后端时，检查selector是否匹配、Pod是否Ready、\\\\u003ccode>targetPort\\\\u003c/code> 是否正确。优先使用EndpointSlice，旧Endpoints接口已逐步弃用。\\\\u003ccode>get networkpolicy\\\\u003c/code> 无资源不代表外部防火墙或平台策略都放行。\\\\u003c/p>\\\\n\\\\u003cp>从已有且具备工具的业务Pod内部验证：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">exec\\\\u003c/span> demo-api-abc-123 -c app -- nslookup cache.demo.svc.cluster.local\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：此域名采用常见的 \\\\u003ccode>cluster.local\\\\u003c/code> 集群域，实际域可不同。镜像无nslookup时，使用已批准的调试容器。先查DNS，再查目标端口、协议、认证、网络策略；同Pod内容器可通过localhost通信，跨Pod不能这样理解。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"11-临时端口转发\\\\\\">11. 临时端口转发\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo port-forward service/demo-api 18080:8080 --address=127.0.0.1\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：8080必须是Service已有端口；保持命令运行，在本机另一个终端访问：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">curl -i --connect-timeout 3 --max-time 5 http://127.0.0.1:18080/health\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>/health\\\\u003c/code> 为应用实际提供的只读检查路径。转发成功不代表Ingress、LoadBalancer或正常Service数据路径都正常；此功能用于临时排查，Pod替换可能使会话中断，按 \\\\u003ccode>Ctrl+C\\\\u003c/code> 停止转发。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"12-pvcpv-与存储故障\\\\\\">12. PVC、PV 与存储故障\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo get pvc -o wide              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 申请状态与容量\\\\u003c/span>\\\\nkubectl -n demo describe pvc demo-data       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 绑定和挂载相关事件\\\\u003c/span>\\\\nkubectl get pv                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 集群级卷\\\\u003c/span>\\\\nkubectl describe pv demo-pv                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 回收策略、绑定、卷属性\\\\u003c/span>\\\\nkubectl get storageclass                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 存储类与绑定模式\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：PVC \\\\u003ccode>Pending\\\\u003c/code> 可能是供给失败、容量、存储类或 \\\\u003ccode>WaitForFirstConsumer\\\\u003c/code> 等待调度；\\\\u003ccode>Bound\\\\u003c/code> 也不代表节点挂载成功，要结合Pod事件。访问模式、挂载权限、文件系统和存储后端状态分别核对。\\\\u003c/p>\\\\n\\\\u003cp>PVC删除可能触发底层卷回收，受PV回收策略及存储实现影响。不要通过删PVC、改finalizer强行解决挂载问题。StatefulSet的扩缩容和卷保留行为也受其配置影响，操作前查清数据生命周期。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"13-job-与-cronjob\\\\\\">13. Job 与 CronJob\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo get \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">jobs\\\\u003c/span>,cronjobs                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 批处理任务\\\\u003c/span>\\\\nkubectl -n demo describe job report-job           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 完成、失败与重试\\\\u003c/span>\\\\nkubectl -n demo logs job/report-job --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span>=100    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 某个任务Pod的日志\\\\u003c/span>\\\\nkubectl -n demo get pods -l job-name=report-job   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 定位全部任务Pod\\\\u003c/span>\\\\nkubectl -n demo create job report-manual-001 --from=cronjob/report \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 手动触发新任务\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：手动触发会实际执行业务，须确认幂等和执行范围；名字需唯一，不能把只读巡检和执行任务混为一谈。多个Pod时分别查看日志。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo patch cronjob report -p \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;{&quot;spec&quot;:{&quot;suspend&quot;:true}}&#x27;\\\\u003c/span>  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 暂停后续调度\\\\u003c/span>\\\\nkubectl -n demo patch cronjob report -p \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;{&quot;spec&quot;:{&quot;suspend&quot;:false}}&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 恢复调度\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：暂停CronJob不会自动终止已经创建的Job；恢复时需考虑错过的调度、并发策略和业务重复执行。以上JSON引号按Linux shell写法，Windows shell需相应调整。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"14-节点排障与计划维护\\\\\\">14. 节点排障与计划维护\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl describe node worker-1                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Conditions、污点、事件\\\\u003c/span>\\\\nkubectl get pods -A --field-selector spec.nodeName=worker-1 -o wide \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 节点上的Pod\\\\u003c/span>\\\\nkubectl -n kube-system get pods -o wide                \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 系统组件\\\\u003c/span>\\\\nkubectl get pdb -A                                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 驱逐预算\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：节点 \\\\u003ccode>NotReady\\\\u003c/code> 时查kubelet、运行时、网络和磁盘压力。节点上有状态服务、local PV或emptyDir时先确认迁移与数据影响。\\\\u003c/p>\\\\n\\\\u003cp>维护操作按步骤执行：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl cordon worker-1                      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 禁止新调度，不迁移已有Pod\\\\u003c/span>\\\\nkubectl drain worker-1 --ignore-daemonsets --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span>=10m \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 驱逐普通工作负载\\\\u003c/span>\\\\nkubectl uncordon worker-1                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 维护验收后恢复调度\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：先确认有其他节点容量且业务可迁移。drain受PDB等约束；默认遇到emptyDir或不受控制器管理的Pod可能中止。不要为通过命令直接加 \\\\u003ccode>--force\\\\u003c/code>、\\\\u003ccode>--delete-emptydir-data\\\\u003c/code> 或绕过驱逐的参数。\\\\u003c/p>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>节点缺少 crictl：安装 cri-tools 并配置运行时端点\\\\u003c/summary>\\\\n\\\\u003cp>仅在需要排查的Kubernetes节点操作，不在普通办公电脑上假设存在运行时socket。优先沿用集群维护的软件源与对应版本。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">command\\\\u003c/span> -v crictl\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Ubuntu / Debian，前提是已配置与集群匹配的Kubernetes软件源\\\\u003c/span>\\\\napt-cache policy cri-tools\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get install cri-tools\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># RHEL系使用其匹配源时，改选：\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># dnf info cri-tools\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># sudo dnf install cri-tools\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># CentOS 7已有节点：仅在现有批准的集群源中查询并选择匹配版本\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># yum --showduplicates list cri-tools\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># sudo yum install cri-tools-具体版本 # 替换成查询出的版本，不自动升级到最新版\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：未配置源时不要直接加入另一小版本仓库；由管理员按集群发行方式提供匹配包，或按照 \\\\u003ca href=\\\\\\"https://github.com/kubernetes-sigs/cri-tools/blob/master/docs/crictl.md\\\\\\">cri-tools安装说明\\\\u003c/a> 下载对应架构的正式发行文件并验证校验和。\\\\u003c/p>\\\\n\\\\u003cp>containerd节点的单次查询示例：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> crictl --runtime-endpoint unix:///run/containerd/containerd.sock info\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> crictl --runtime-endpoint unix:///run/containerd/containerd.sock ps -a\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：socket路径以实际containerd配置为准；CRI-O、K3s、RKE2等可能使用不同端点。确认后可由管理员配置 \\\\u003ccode>/etc/crictl.yaml\\\\u003c/code>，不要把私有socket开放成所有用户可写。\\\\u003c/p>\\\\n\\\\u003c/details>\\\\n\\\\u003cp>登录目标节点后的只读检查，需匹配实际运行时：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">systemctl status kubelet --no-pager -l         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># kubelet状态\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -u kubelet -b -n 100 --no-pager \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 日志\\\\u003c/span>\\\\nsystemctl status containerd --no-pager -l      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 使用containerd时\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> crictl ps -a                             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># CRI容器，需已正确配置endpoint\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> crictl pods                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Pod沙箱\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -h                                        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 磁盘空间\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -i                                        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># inode\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：现代Kubernetes不要求使用Docker，不能默认通过 \\\\u003ccode>docker ps\\\\u003c/code> 看见所有Pod容器。先确认节点运行时与crictl连接端点，不用运行时命令绕过Kubernetes直接删除业务容器。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"15-rbacserviceaccount标签与污点\\\\\\">15. RBAC、ServiceAccount、标签与污点\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl auth can-i get pods -n demo             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前身份能否查询\\\\u003c/span>\\\\nkubectl auth can-i create pods/exec -n demo     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 能否进入容器\\\\u003c/span>\\\\nkubectl -n demo get serviceaccounts,roles,rolebindings \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 命名空间权限配置\\\\u003c/span>\\\\nkubectl get clusterroles,clusterrolebindings    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 集群权限配置\\\\u003c/span>\\\\nkubectl -n demo get pods --show-labels          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Pod标签\\\\u003c/span>\\\\nkubectl get nodes --show-labels                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 节点标签\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>Forbidden\\\\u003c/code> 先确认身份、context和RBAC，不能通过临时授予cluster-admin来替代定位。\\\\u003ccode>can-i\\\\u003c/code>只是当前权限判断，仍可能被准入策略约束。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl label node worker-1 workload=batch          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 新增调度相关标签\\\\u003c/span>\\\\nkubectl label node worker-1 workload-               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 移除标签\\\\u003c/span>\\\\nkubectl taint node worker-1 dedicated=batch:NoSchedule \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 增加污点\\\\u003c/span>\\\\nkubectl taint node worker-1 dedicated:NoSchedule-    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 删除污点\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：标签和污点可能改变后续调度，不作为无害的查询命令。\\\\u003ccode>NoSchedule\\\\u003c/code> 一般阻止不容忍的新Pod；\\\\u003ccode>NoExecute\\\\u003c/code> 还可能驱逐已有Pod，不能随意替换。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"16-删除操作与排障顺序\\\\\\">16. 删除操作与排障顺序\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo delete pod demo-api-abc-123 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 优雅删除指定Pod，可能被重建\\\\u003c/span>\\\\nkubectl -n demo delete -f obsolete.yaml     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 删除清单对应资源，逐项核对\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：删除前核对对象、控制器和数据归属；删除namespace会删除其中大量资源，不能当成重启。强制删除Pod不保证原节点上的进程已真正结束，有状态服务可能出现双写，避免常规使用。\\\\u003c/p>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>现象\\\\u003c/th>\\\\n\\\\u003cth>排查顺序\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Pending\\\\u003c/td>\\\\n\\\\u003ctd>describe事件 → requests/容量 → 污点/亲和性 → PVC\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>ImagePullBackOff\\\\u003c/td>\\\\n\\\\u003ctd>镜像名/digest → 凭证 → 节点网络/DNS/证书 → 架构\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>CrashLoopBackOff\\\\u003c/td>\\\\n\\\\u003ctd>previous日志 → 退出原因 → 配置/权限 → 依赖 → 探针\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>OOMKilled\\\\u003c/td>\\\\n\\\\u003ctd>limit → 峰值与泄漏 → 节点压力 → 应用内存配置\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Running但不Ready\\\\u003c/td>\\\\n\\\\u003ctd>readiness结果 → 应用监听 → 配置与依赖\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Service不可达\\\\u003c/td>\\\\n\\\\u003ctd>Pod就绪 → selector → EndpointSlice → targetPort → 网络策略\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Ingress 502/504\\\\u003c/td>\\\\n\\\\u003ctd>入口控制器 → Service → 后端端口与协议 → 应用超时\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Node NotReady\\\\u003c/td>\\\\n\\\\u003ctd>kubelet → 运行时 → 网络插件 → 磁盘/内存/证书\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>FailedMount\\\\u003c/td>\\\\n\\\\u003ctd>PVC/PV → 节点事件 → 存储驱动 → 权限和后端\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Forbidden\\\\u003c/td>\\\\n\\\\u003ctd>当前context与身份 → RBAC → 准入限制\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>liveness失败可能重启容器，readiness失败影响流量就绪，startup探针保护启动阶段。不要把业务暂不可用直接等同于应该删Pod重启。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"17-发布后的验收清单\\\\\\">17. 发布后的验收清单\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">kubectl -n demo rollout status deployment/demo-api --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span>=180s\\\\nkubectl -n demo get pods -l app=demo-api -o wide\\\\nkubectl -n demo get events --sort-by=.metadata.creationTimestamp\\\\nkubectl -n demo logs deployment/demo-api --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span>=100\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：确认副本就绪、重启次数不持续增长、无新增关键告警，并从真实入口验证只读接口和关键业务。最后一条可能只选择一个Pod，多个副本需结合标签聚合或集中日志检查。\\\\u003c/p>\\\\n\\\\u003cp>命令和可用参数以客户端与集群版本为准，详见 \\\\u003ca href=\\\\\\"https://kubernetes.io/docs/reference/kubectl/quick-reference/\\\\\\">kubectl 官方速查\\\\u003c/a>。另见 \\\\u003ca href=\\\\\\"docker-compose-operations-commands.html\\\\\\">Docker 与 Compose 运维\\\\u003c/a>、\\\\u003ca href=\\\\\\"linux-server-operations-commands.html\\\\\\">服务器常用命令\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"18-按场景查看完整步骤\\\\\\">18. 按场景查看完整步骤\\\\u003c/h2>\\\\n\\\\u003cul>\\\\n\\\\u003cli>\\\\u003ca href=\\\\\\"kubernetes-application-practice.html\\\\\\">Kubernetes 应用部署与配置实践\\\\u003c/a>：完整清单、配置生效、探针、更新与回退。\\\\u003c/li>\\\\n\\\\u003cli>\\\\u003ca href=\\\\\\"kubernetes-cluster-troubleshooting.html\\\\\\">Kubernetes 集群搭建、维护与故障排查\\\\u003c/a>：实验集群、运行时、节点、网络、存储和维护流程。\\\\u003c/li>\\\\n\\\\u003c/ul>\\\\n\\\\u003c/article>\\\\u003cdiv class=\\\\\\"article-end\\\\\\">\\\\u003cspan>— 本文结束 —\\\\u003c/span>\\\\u003ca href=\\\\\\"../index.html\\\\\\">返回知识库首页 ↗\\\\u003c/a>\\\\u003c/div>\\",\\"toc\\":[{\\"title\\":\\"1. 集群、上下文和命名空间\\",\\"level\\":2,\\"id\\":\\"1-集群上下文和命名空间\\"},{\\"title\\":\\"2. 全局巡检与资源列表\\",\\"level\\":2,\\"id\\":\\"2-全局巡检与资源列表\\"},{\\"title\\":\\"3. 定位应用与查看详情\\",\\"level\\":2,\\"id\\":\\"3-定位应用与查看详情\\"},{\\"title\\":\\"4. 日志：当前、上次、多个容器\\",\\"level\\":2,\\"id\\":\\"4-日志当前上次多个容器\\"},{\\"title\\":\\"5. 容器命令、文件复制和临时调试\\",\\"level\\":2,\\"id\\":\\"5-容器命令文件复制和临时调试\\"},{\\"title\\":\\"6. CPU、内存、限制与 OOM\\",\\"level\\":2,\\"id\\":\\"6-cpu内存限制与-oom\\"},{\\"title\\":\\"7. 清单校验、比较与应用\\",\\"level\\":2,\\"id\\":\\"7-清单校验比较与应用\\"},{\\"title\\":\\"8. 更新、重启、回滚与扩缩容\\",\\"level\\":2,\\"id\\":\\"8-更新重启回滚与扩缩容\\"},{\\"title\\":\\"9. ConfigMap、Secret 和配置生效\\",\\"level\\":2,\\"id\\":\\"9-configmapsecret-和配置生效\\"},{\\"title\\":\\"10. Service、DNS、EndpointSlice 与 Ingress\\",\\"level\\":2,\\"id\\":\\"10-servicednsendpointslice-与-ingress\\"},{\\"title\\":\\"11. 临时端口转发\\",\\"level\\":2,\\"id\\":\\"11-临时端口转发\\"},{\\"title\\":\\"12. PVC、PV 与存储故障\\",\\"level\\":2,\\"id\\":\\"12-pvcpv-与存储故障\\"},{\\"title\\":\\"13. Job 与 CronJob\\",\\"level\\":2,\\"id\\":\\"13-job-与-cronjob\\"},{\\"title\\":\\"14. 节点排障与计划维护\\",\\"level\\":2,\\"id\\":\\"14-节点排障与计划维护\\"},{\\"title\\":\\"15. RBAC、ServiceAccount、标签与污点\\",\\"level\\":2,\\"id\\":\\"15-rbacserviceaccount标签与污点\\"},{\\"title\\":\\"16. 删除操作与排障顺序\\",\\"level\\":2,\\"id\\":\\"16-删除操作与排障顺序\\"},{\\"title\\":\\"17. 发布后的验收清单\\",\\"level\\":2,\\"id\\":\\"17-发布后的验收清单\\"},{\\"title\\":\\"18. 按场景查看完整步骤\\",\\"level\\":2,\\"id\\":\\"18-按场景查看完整步骤\\"}],\\"standaloneTitle\\":\\"\\"}"},"headers":[],"relativePath":"articles/kubernetes-operations-commands.md","filePath":"articles/kubernetes-operations-commands.md"}'),n={name:"articles/kubernetes-operations-commands.md"};function u(a,t,l,o,p,d){return e(),s("div")}const m=c(n,[["render",u]]);export{r as __pageData,m as default};
